            let name = n
                .child_by_field_name("name")
                .map(|f| node_text(f, source).to_string())
                .unwrap_or_default();
            out.push((n, name));
        }
        let mut cursor = n.walk();
        for child in n.children(&mut cursor) {
            stack.push(child);
