// Helpers
// ---------------------------------------------------------------------------

/// Extract the source text covered by a node.
pub(crate) fn node_text<'a>(node: tree_sitter::Node, source: &'a str) -> &'a str {
    &source[node.start_byte()..node.end_byte()]
}

