    pub(crate) fn check_spmd_gp_assignment(
        &self,
        root: tree_sitter::Node,
        source: &str,
        symbol_table: &SymbolTable,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let mut gp_names: HashSet<String> = HashSet::new();
        for scope in &symbol_table.scopes {
            for def in &scope.defs {
                if matches!(def.kind, DefKind::Global | DefKind::Persistent) {
                    gp_names.insert(def.name.clone());
                }
            }
        }
        if gp_names.is_empty() {
            return;
        }
        self.spmd_gp_assignment_dfs(root, source, &gp_names, false, diagnostics);
    }

    /// DFS helper for [`Self::check_spmd_gp_assignment`].
    fn spmd_gp_assignment_dfs(
        &self,
        node: tree_sitter::Node,
        source: &str,
        gp_names: &HashSet<String>,
        in_spmd: bool,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        match node.kind() {
            "spmd_statement" => {
                let mut cursor = node.walk();
                for child in node.children(&mut cursor) {
                    self.spmd_gp_assignment_dfs(child, source, gp_names, true, diagnostics);
                }
                return;
            }
            "function_definition" => {
                // Global/persistent scoping does not cross function boundaries;
                // do not descend into nested/local function bodies.
                return;
            }
            "assignment" if in_spmd => {
                if let Some(name) = self.assignment_lhs_var_name(node, source) {
                    if gp_names.contains(&name) {
                        self.push_diag(
                            node,
                            "SPGP",
                            &format!(
                                "Setting the GLOBAL or PERSISTENT variable {name} in an SPMD block might fail because the set happens on a worker machine."
                            ),
                            diagnostics,
                        );
                    }
                }
            }
            _ => {}
        }
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            self.spmd_gp_assignment_dfs(child, source, gp_names, in_spmd, diagnostics);
        }
    }

    /// Extract the variable name assigned to, handling both simple (`x = ...`)
    /// and indexed (`x(i) = ...`) left-hand sides.
    fn assignment_lhs_var_name(&self, node: tree_sitter::Node, source: &str) -> Option<String> {
        let lhs = node.child_by_field_name("left")?;
        match lhs.kind() {
            "identifier" => Some(node_text(lhs, source).to_string()),
            "function_call" => callee_name(lhs, source),
            _ => None,
        }
    }
}

